function renderAbilityFacts(source){return abilityFacts(source).map(([label,value])=>`<div class="ability-fact"><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('');}
function renderLegacyFeatGrant(source){const n=abilityState().legacyGrants[source.id]||0;if(!n)return '';return `<div class="ability-rule-note"><p>${esc(source.title)} был выбран до автоматической выдачи очков. Выдача за ${n} взятие(-я) уже учтена вручную?</p><div class="ability-actions"><button data-ability-legacy="${source.id}" data-credit="no">Уже учтено</button><button data-ability-legacy="${source.id}" data-credit="yes">Выдать неучтённые очки</button></div></div>`;}
function abilityCard(source){const model=effectsForSource(source),active=model.cfg.enabled!==false,actions=ABILITY_ACTIONS[source.title]||[];return `<article class="ability-card"><details><summary>${esc(source.title)}${!active?' · выключено':''}</summary><p>${esc(ABILITY_NOTES[source.title]||'')}</p>${renderAbilityFacts(source)}<div class="ability-actions">${actions.map((a,i)=>{const limit=abilityLimit(a),used=abilityUses(source,a);return `<button data-ability-use="${source.id}" data-action-index="${i}" ${!active||used>=limit?'disabled':''}>${esc(a.label)}${Number.isFinite(limit)?' · '+Math.max(0,limit-used)+' / '+limit:''}</button>`;}).join('')}<button data-effect-source="${source.id}">⚙ Источники и условия</button></div><details><summary>Полное правило и требования</summary><p class="rule-text">${esc(source.text)}</p><a href="${source.url}" target="_blank" rel="noopener">Sacralic ↗</a></details></details></article>`;}
function renderAbilityPanel(){const sources=selectedEffectSources().filter(s=>ABILITY_CATEGORIES.includes(s.category));const r=abilityState();return `<section class="panel ability-control-panel"><div class="section-heading"><h2>Способности · применение</h2><button data-ability="help">i</button></div><div class="ability-resource-line"><span>EP <b>${currentEnergy()} / ${energyValues().max}</b></span>${r.tempHp?`<span>Временные HP <b>${r.tempHp}</b></span>`:''}${r.stance?`<span>${esc(r.stance.name)} · ${r.stance.until-state.play.round} раунд.</span><button data-ability="end-stance">Выйти из стойки</button>`:''}${r.offgameUntil>state.play.round?`<span>Вне игры · ${r.offgameUntil-state.play.round} раунд.</span>`:''}${r.incapacitated?'<b>После «9 жизней»: активные действия запрещены до конца суток</b>':''}</div><div class="ability-actions"><button data-ability="psi">Применить пси-способность</button><button data-ability="energy">Изменить EP</button><button data-ability="reset" data-period="battle">Новый бой</button><button data-ability="reset" data-period="day">Новые сутки</button><button data-ability="reset" data-period="conversation">Новый разговор</button><button data-ability="reset" data-period="quest">Новый квест</button></div>${r.errorDebt?'<p class="ability-rule-note">Право на ошибку: ожидается штрафной провал.</p>':''}${sources.map(abilityCard).join('')||'<p class="help-copy">Выберите фиты и престиж-класс, чтобы видеть их действия и источники.</p>'}</section>`;}
function renderMeleeMoves(){const moves=RULE_ENTRIES.filter(e=>e.category==='Приёмы'),selected=learnedMoves(),skills=meleeSkills(),slots=meleeMoveSlots();return `<section class="panel selected-techniques ability-melee-panel"><div class="section-heading"><h2>Приёмы ближнего боя</h2><button data-ability="moves">+ Выбрать приёмы</button></div><span class="muted">Выбрано ${selected.length} / открыто ${slots}</span>${!skills.length?'<p>Добавьте силовой или ловкий ближний бой.</p>':''}${selected.map(entry=>`<article class="ability-card"><details><summary>${esc(entry.title)}</summary><p class="rule-text">${esc(entry.text)}</p>${moveRequirements(entry).length?`<p class="ability-rule-note">Требования: ${esc(moveRequirements(entry).join(', '))}</p>`:''}</details><button data-ability-move="${entry.id}">Применить приём</button></article>`).join('')}${skills.length&&!selected.length?'<p class="help-copy">В окне выбора доступны все 14 приёмов, включая стойки и комбинацию.</p>':''}</section>`;}
const beforeLegacyAbilityCard=abilityCard;
abilityCard=function(source){return beforeLegacyAbilityCard(source).replace('</article>',renderLegacyFeatGrant(source)+'</article>');};
const beforeLegacySummaryFeats=renderSummaryFeats;
renderSummaryFeats=function(){return beforeLegacySummaryFeats()+(Object.keys(abilityState().legacyGrants).length?'<button data-page="5">Проверить старую выдачу очков фитов →</button>':'');};
const beforeAbilityCombatPage=renderCombatPage;
renderCombatPage=function(){return beforeAbilityCombatPage().replace(/<section class="panel selected-techniques">[\s\S]*?<\/section>/,'')+renderMeleeMoves()+renderAbilityPanel();};
const beforeAbilityAbilitiesPage=renderAbilities;
renderAbilities=function(){return beforeAbilityAbilitiesPage()+renderAbilityPanel();};
const beforeAbilitySourceSettings=renderSourceSettings;
function renderAbilityPicks(source,count,configuration){const cfg=configuration||sourceConfig(source.id),choices=effectsForSource(source,{...cfg,count:1}).choices;return TARGET_FEATS.includes(source.title)&&count>1?Array.from({length:count},(_,i)=>`<fieldset class="ability-pick"><legend>Взятие ${i+1}</legend>${choices.map(choice=>{const picked={...cfg,...cfg.picks?.[i]};return renderEffectChoice(choice,picked).replace('data-effect-choice="'+choice.key+'"','data-ability-pick="'+i+'" data-pick-key="'+choice.key+'"');}).join('')}</fieldset>`).join(''):'';}
function refreshAbilityPickEditor(count){const s=selectedEffectSources().find(s=>s.id===effectsOpenSource),el=document.querySelector('#ability-picks');if(!s||!el||!Number.isInteger(count)||count<1||count>50)return;const cfg={...sourceConfig(s.id),picks:structuredClone(sourceConfig(s.id).picks||[])};for(const input of document.querySelectorAll('[data-effect-choice]'))cfg[input.dataset.effectChoice]=input.value;for(const input of document.querySelectorAll('[data-ability-pick]'))(cfg.picks[+input.dataset.abilityPick]??={})[input.dataset.pickKey]=input.value;el.innerHTML=renderAbilityPicks(s,count,cfg);}
renderSourceSettings=function(id){const source=selectedEffectSources().find(s=>s.id===id),html=beforeAbilitySourceSettings(id);if(!source||!ABILITY_CATEGORIES.includes(source.category))return html;return html.replace('<h3>ЧИСЛОВЫЕ ЭФФЕКТЫ</h3>',`<div id="ability-picks">${renderAbilityPicks(source,Math.max(1,sourceConfig(id).count||1))}</div><p>${esc(ABILITY_NOTES[source.title]||'')}</p>${renderAbilityFacts(source)}<h3>ЧИСЛОВЫЕ ЭФФЕКТЫ</h3>`).replace(/<p class="help-copy">Правила, меняющие выбор цели,[\s\S]*?<\/p>/,'<p class="help-copy">Числовые эффекты и выбранные цели рассчитываются автоматически. Действия, EP и счётчики — в «Способности · применение»; выбор целей и события мира подтверждает ведущий.</p>');};
const beforeAbilitySaveSource=saveSourceSettings;
saveSourceSettings=function(){
 const id=effectsOpenSource,picks=[],manual=document.querySelector('#ability-manual-chance'),raw=manual?.value.trim(),spy=[...document.querySelectorAll('[data-ability-spy]')].map(el=>({skill:el.dataset.abilitySpy,levels:Number(el.value)}));
 if(raw&&!Number.isFinite(Number(raw)))throw Error('Введите числовой шанс N.');if(spy.some(a=>!Number.isSafeInteger(a.levels)||a.levels<0||a.levels>50))throw Error('Уровни перевоплощения: целые от 0 до 50.');
 for(const input of document.querySelectorAll('[data-ability-pick]'))(picks[+input.dataset.abilityPick]??={})[input.dataset.pickKey]=input.value;
 beforeAbilitySaveSource();if(picks.length)state.effects.sources[id].picks=picks;if(spy.length)state.effects.sources[id].spyAllocations=spy.filter(a=>a.levels);
 if(manual){if(raw)state.effects.sources[id].manualChance=Number(raw);else delete state.effects.sources[id].manualChance;}
};
const beforeAbilityManualSource=renderSourceSettings;
renderSourceSettings=function(id){const source=selectedEffectSources().find(s=>s.id===id);let html=beforeAbilityManualSource(id);if(source?.title==='Серая мышь')html=html.replace('<h3>ЧИСЛОВЫЕ ЭФФЕКТЫ</h3>',`<label>Шанс N, определённый ведущим<input id="ability-manual-chance" type="number" value="${sourceConfig(id).manualChance??''}"></label><h3>ЧИСЛОВЫЕ ЭФФЕКТЫ</h3>`);if(source?.title==='Шпион')html=html.replace('<h3>ЧИСЛОВЫЕ ЭФФЕКТЫ</h3>',`<fieldset class="ability-pick"><legend>Пул перевоплощения · ${Math.floor(effectsForSource(source).level/3)} SP</legend><p>Временные уровни оплачиваются из отдельного пула по обычной стоимости повышения. Отрицательный остаток виден в расчёте; мастер может разрешить исключение.</p>${state.skills.map(s=>`<label>${esc(s[0])}<input data-ability-spy="${esc(skillIdentity(s))}" type="number" min="0" max="50" step="1" value="${sourceConfig(id).spyAllocations?.find(a=>a.skill===skillIdentity(s))?.levels||0}"></label>`).join('')}</fieldset><h3>ЧИСЛОВЫЕ ЭФФЕКТЫ</h3>`);return html;};
const beforeAbilityFormulaDialog=renderFormulaDialog;
renderFormulaDialog=function(){const html=beforeAbilityFormulaDialog();if(formulaOpen<0)return html;const s=state.skills[formulaOpen],classes=classSkillSources(s);return html.replace('<div class="dialog-actions">',`<p>Предел навыка с выбранными фитами: <b>${skillMaximum(s)}</b>${classes.length?' · классовый: '+esc(classes.join(', ')):''}</p><div class="dialog-actions">`);};
const beforeAbilityAttackCards=renderAvailableAttacks;
renderAvailableAttacks=function(){let i=0;const weapons=state.items.filter(item=>item.category==='Оружие'&&item.equipped);return beforeAbilityAttackCards().replace(/<\/article>/g,()=>{const a=attackNumbers(weapons[i++]);return `<div class="ability-attack-facts">Крит ${a.criticalChance}%${a.criticalPowerBonus?' · показатель ('+a.criticalPowerBonus+')':''}${a.criticalMultiplierBonus?' · множитель урона ('+a.criticalMultiplierBonus+')':''}${a.damageFactor?' · итоговый урон ×'+a.damageFactor:''}${a.targets?' · целей '+a.targets:''}</div></article>`;});};
const beforeAbilityWeapons=renderWeapons;
renderWeapons=function(){let i=0;const weapons=state.items.filter(item=>item.category==='Оружие'&&item.equipped);return beforeAbilityWeapons().replace(/<\/article>/g,()=>{const item=weapons[i++];if(!item)return '</article>';const a=attackNumbers(item);return `<div class="ability-attack-facts"><b>Итог: ${a.chance??'—'}%</b> · ${esc(a.damage)}${a.damageFactor?' ×'+a.damageFactor:''} · ББ ${a.bb??'—'} · ${a.cost??'—'} ОД · крит ${a.criticalChance}%${a.criticalMultiplierBonus?' · множитель крит. урона ('+a.criticalMultiplierBonus+')':''}<details><summary>Источники расчёта</summary>${a.notes.map(n=>'<p>'+esc(n)+'</p>').join('')}</details></div></article>`;});};
const beforeAbilityActionPanel=renderActionPanel;
renderActionPanel=function(){const m=movementValues();return beforeAbilityActionPanel().replace(metric('Шаг / бег',state.play.walk+' / '+state.play.run,'клеток за ОД'),metric('Шаг / бег',m.walk+' / '+m.run,'клеток за ОД')).replace('клеток за 2 ОД','клеток за '+m.jumpCost+' ОД');};
const beforeAbilityArmorCalculator=renderArmorCalculator;
renderArmorCalculator=function(){const base=state.zones[zone].armor,ar=resolveEffectTarget(base,'armor').value;return beforeAbilityArmorCalculator().replace('id="armor-ar" type="number" min="0" value="'+base+'"','id="armor-ar" type="number" min="0" value="'+ar+'"')+(ar!==base?'<p class="ability-rule-note">AR включает бонусы выбранного престиж-класса.</p>':'');};
const beforeAbilityDeathTracker=renderDeathTracker;
renderDeathTracker=function(){const html=beforeAbilityDeathTracker();return abilitySource('Отключение болевого порога')?html.replace('Три накопленных провала — смерть.','Три провала стойкости — без сознания (Отключение болевого порога).').replace('Достигнут порог смерти по правилу трёх провалов.','Без сознания вместо смерти от болевого шока. Другие причины смерти разрешаются отдельно.'):html;};
const beforeAbilityProgression=renderProgression;
renderProgression=function(){return beforeAbilityProgression().replace('<div class="xp-adjust">','<div class="xp-adjust"><label class="ability-xp-type">Тип опыта<select id="ability-xp-type"><option value="raw">Без бонуса</option><option value="combat">Боевой</option><option value="peaceful">Мирный</option></select></label>');};
const beforeAbilityAdjustXp=adjustXp;
adjustXp=function(add){const type=document.querySelector('#ability-xp-type')?.value;if(!add||!['combat','peaceful'].includes(type))return beforeAbilityAdjustXp(add);const raw=Number(document.querySelector('#xp-amount').value);if(!Number.isSafeInteger(raw)||raw<0){toast('Опыт — целое число от 0.');return false;}const amount=Math.floor(resolveEffectTarget(raw,'xp:'+type).value);if(!Number.isSafeInteger(state.info.xp+amount)){toast('Слишком большое значение опыта.');return false;}state.info.xp+=amount;return true;};
const ABILITY_TARGETS={armor:'Броня AR',energy:'Максимальные EP',criticalMultiplier:'Бонус множителя критического урона',incomingCriticalPower:'Поправка входящего показателя крита',counterChance:'Бонус контрудара',fumbleAura:'Аура критического неуспеха',reputation:'Репутация','xp:combat':'Получаемый боевой опыт','xp:peaceful':'Получаемый мирный опыт'};
const beforeAbilityTargetLabel=effectTargetLabel;
effectTargetLabel=function(key){return ABILITY_TARGETS[key]||beforeAbilityTargetLabel(key);};
const beforeAbilityEffectsPage=renderEffectsPage;
renderEffectsPage=function(){let html=beforeAbilityEffectsPage();const options=Object.keys(ABILITY_TARGETS).map(key=>`<option value="${key}">${esc(effectTargetLabel(key))}</option>`).join('');for(const id of ['effect-override-target','effect-custom-target'])html=html.replace('<select id="'+id+'">','<select id="'+id+'">'+options);return html+'<section class="panel"><h3>БОЕВЫЕ И РЕСУРСНЫЕ БОНУСЫ</h3><div class="rule-grid">'+Object.keys(ABILITY_TARGETS).map(renderTargetBreakdown).join('')+'</div></section>';};
const beforeAbilityBaseValue=targetBaseValue;
targetBaseValue=function(key){if(key==='energy')return beforeAbilityEnergy().max;if(key.startsWith('xp:')||key==='reputation')return 1;return beforeAbilityBaseValue(key);};
function abilitySkillOptions(filter=()=>true){return state.skills.filter(filter).map(s=>`<option value="${esc(skillIdentity(s))}">${esc(s[0])} · ${effectiveSkillLevel(s)}</option>`).join('');}
function abilityWeaponOptions(melee=false){return state.items.map((item,index)=>({item,index})).filter(({item})=>item.category==='Оружие'&&item.equipped&&(!melee||weaponSkillKey(item)?.startsWith('Ближний бой'))).map(({item,index})=>`<option value="${index}">${esc(item.name)}</option>`).join('');}
function renderAbilityDialog(){
 if(!abilityDialog)return '';const d=abilityDialog;let body='',title='',action='';
 if(d.kind==='moves'){title='Все приёмы Sacralic';body=RULE_ENTRIES.filter(e=>e.category==='Приёмы').map(e=>`<article class="ability-card"><div class="section-heading"><b>${esc(e.title)}</b><button data-ability-select-move="${e.id}" aria-pressed="${state.play.pinned.includes(e.id)}">${state.play.pinned.includes(e.id)?'Убрать':'Выбрать'}</button></div><p>${esc(e.text)}</p>${moveRequirements(e).length?`<small>Требования: ${esc(moveRequirements(e).join(', '))}</small>`:''}</article>`).join('');}
 if(d.kind==='move'){const entry=RULE_ENTRIES.find(e=>e.id===d.id);title=entry.title;body=`<p class="rule-text">${esc(entry.text)}</p><label>Навык<select id="ability-skill">${abilitySkillOptions(s=>combatKey(s)?.startsWith('Ближний бой'))}</select></label><label>Оружие<select id="ability-weapon"><option value="">Без оружия / ручная база</option>${abilityWeaponOptions(true)}</select></label><div class="fields"><label>ОД обычного удара<input id="ability-base-cost" type="number" min="1" value="${abilityState().meleeBase.cost??''}"></label><label>Базовый урон без оружия<input id="ability-base-damage" value="${esc(abilityState().meleeBase.damage)}" placeholder="Укажите по правилам атаки"></label></div>${entry.title==='Комбинация'?`<div class="fields"><label>Первый приём<select id="ability-combo-first">${learnedMoves().filter(e=>e.title!=='Комбинация'&&!/стойка$/.test(e.title)).map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></label><label>Второй приём<select id="ability-combo-second">${learnedMoves().filter(e=>e.title!=='Комбинация'&&!/стойка$/.test(e.title)).map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></label><label>ОД комбинации по решению мастера<input id="ability-combo-cost" type="number" min="0"></label></div>`:''}<div id="ability-move-preview"></div><label class="check-row"><input id="ability-gm" type="checkbox">Мастер разрешил исключение из требований</label>`;action='execute-move';}
 if(d.kind==='use'){const source=selectedEffectSources().find(s=>s.id===d.id),a=ABILITY_ACTIONS[source.title][d.index];title=source.title+' · '+a.label;body=`<p>${esc(ABILITY_NOTES[source.title])}</p>${renderAbilityFacts(source)}${['charge','allies','epDamage','reputation','vehicle','spirit'].includes(a.id)?`<label>${({charge:'Клеток пройдено с атакой',allies:'Количество союзников',epDamage:'Урон, оплачиваемый EP',reputation:'Изменение репутации (со знаком)',vehicle:'Базовые HP транспорта',spirit:'X — количество d100'})[a.id]}<input id="ability-value" type="number" value="0" step="1"></label>`:''}${['counter','song','repair'].includes(a.id)?`<label>Навык<select id="ability-skill">${abilitySkillOptions(a.id==='counter'?s=>combatKey(s)?.startsWith('Ближний бой'):a.id==='repair'?s=>/ремонт/i.test(s[0]):s=>/музык|искусств|исполн/i.test(s[0]))}</select></label>`:''}${['charge','burst'].includes(a.id)?`<label>Оружие<select id="ability-weapon">${abilityWeaponOptions(a.id==='charge')}</select></label>`:''}${a.id==='life'?'<label class="check-row"><input id="ability-gm" type="checkbox">Мастер подтвердил смертельное событие</label>':''}`;action='execute-use';}
 if(d.kind==='psi'){title='Пси-способность · расход EP';body=`<label>Дисциплина<select id="ability-skill">${abilitySkillOptions(isPsiSkill)}</select></label><label>Стоимость EP<input id="ability-value" type="number" min="0" step="1" value="0"></label><label class="check-row"><input id="ability-critical" type="checkbox">Подтверждён критический успех</label>${abilitySource('Варден')?'<label class="check-row"><input id="ability-hp" type="checkbox">Оплатить HP: 10 HP за 1 EP</label>':''}<p>Сейчас ${currentEnergy()} / ${energyValues().max} EP. Расход ОД самой способности вводится в панели ОД.</p>`;action='execute-psi';}
 if(d.kind==='energy'){title='Изменить EP';body=`<label>Изменение EP (восстановление +, трата −)<input id="ability-value" type="number" step="1" value="0"></label>${abilitySource('Варден')?'<p>Варден не восстанавливает себя самостоятельно, кроме естественной регенерации.</p><label class="check-row"><input id="ability-gm" type="checkbox">Разрешённый источник подтверждён</label>':''}`;action='execute-energy';}
 if(d.kind==='reset'){title='Подтвердить новый период';body=`<p>Начать новый период: ${esc({battle:'бой',day:'сутки',conversation:'разговор',quest:'квест'}[d.period])}? Восстановятся только счётчики этого периода. Заряды «9 жизней» не восстанавливаются.</p>${d.period==='day'?'<p>Используйте, когда прошли игровые сутки. Снимается запрет активных действий после «9 жизней».</p>':''}`;action='execute-reset';}
 if(d.kind==='help'){title='Автоматизация способностей';body='<p>Числовые бонусы и расходы рассчитываются из выбранных источников. Настройки позволяют отключать или заменять каждую величину. Кнопки применения отслеживают ОД, EP, заряды и периоды.</p><p>Выбор целей, правдивость утверждений, трофеи, сюжетные события, иммунитеты целей и ответные защитные броски разрешает ведущий. Они показаны полным текстом, без выдуманных автоматических исходов.</p>';}
 if(d.kind==='use'){const source=selectedEffectSources().find(s=>s.id===d.id),a=ABILITY_ACTIONS[source.title][d.index];if(a.id==='dual')body+=`<div class="fields"><label>Первое оружие<select id="ability-weapon">${abilityWeaponOptions()}</select></label><label>Второе оружие<select id="ability-weapon-second">${abilityWeaponOptions()}</select></label></div><p>ОД = стоимость медленного оружия +1; каждый бросок получает штраф 10 п.п.</p>`;if(a.id.startsWith('untrained'))body+='<label>Базовый шанс без навыка, до бонуса фита<input id="ability-value" type="number" step="any" placeholder="Уточните базу у мастера"></label>';if(a.id==='work')body+=`<label>Базовые очки работы<input id="ability-value" type="number" min="0" value="0"></label><label>Навык<select id="ability-skill">${abilitySkillOptions()}</select></label>`;}
 return `<dialog id="ability-dialog" class="formula-dialog" aria-labelledby="ability-dialog-title"><div class="toolbar"><h2 id="ability-dialog-title">${esc(title)}</h2><button data-ability="close" aria-label="Закрыть способности">×</button></div>${body}<p id="ability-error" class="formula-error" role="status"></p>${action?`<div class="dialog-actions"><button data-ability="close">Отмена</button><button data-ability="${action}">Подтвердить</button></div>`:''}</dialog>`;
}
function openAbilityDialog(data){abilityDialog=data;document.querySelector('#ability-dialog')?.remove();document.querySelector('#view').insertAdjacentHTML('beforeend',renderAbilityDialog());document.querySelector('#ability-dialog').showModal();refreshMovePreview();}
function closeAbilityDialog(){abilityDialog=null;document.querySelector('#ability-dialog')?.remove();}
function refreshMovePreview(){if(abilityDialog?.kind!=='move')return;const el=document.querySelector('#ability-move-preview');try{const entry=RULE_ENTRIES.find(e=>e.id===abilityDialog.id),skill=state.skills.find(s=>skillIdentity(s)===document.querySelector('#ability-skill').value),index=document.querySelector('#ability-weapon').value,item=index===''?null:state.items[+index],raw=document.querySelector('#ability-base-cost').value,m=meleeMoveNumbers(entry,skill,item,raw===''?null:Number(raw));el.innerHTML=`<div class="ability-resource-line"><b>${m.cost??'Укажите'} ОД</b><b>${m.chance??'Отдельные броски'}${m.chance!==null?'%':''}</b><span>Урон ${esc(m.damage)}${m.damageFactor!==1?' ×'+m.damageFactor:''}</span><span>Защита ${esc(m.defense)}</span></div>${m.armorIgnore?`<p>Игнорирует ${m.armorIgnore*100}% обычной брони; естественная броня сохраняется.</p>`:''}`;}catch(error){el.textContent=error.message;}}
const beforeAbilityUiRender=render;
render=function(){beforeAbilityUiRender();if(libraryHome)return;if(abilityResult&&page===4)document.querySelector('.ability-control-panel')?.insertAdjacentHTML('afterbegin',`<p class="ability-rule-note" role="status">${esc(abilityResult)}</p>`);if(abilityDialog){document.querySelector('#view').insertAdjacentHTML('beforeend',renderAbilityDialog());document.querySelector('#ability-dialog').showModal();refreshMovePreview();}};
document.addEventListener('cancel',e=>{if(e.target.id==='ability-dialog')closeAbilityDialog();},true);
document.addEventListener('input',e=>{if(e.target.id==='effect-count')refreshAbilityPickEditor(Number(e.target.value));},true);
document.addEventListener('change',e=>{if(e.target.closest('#ability-dialog')){e.stopImmediatePropagation();refreshMovePreview();}if(e.target.id==='effect-count'&&effectsOpenSource){const s=selectedEffectSources().find(s=>s.id===effectsOpenSource),n=Number(e.target.value);if(s&&Number.isInteger(n)&&n>=1&&n<=50)document.querySelector('#ability-picks').innerHTML=renderAbilityPicks(s,n);}},true);
document.addEventListener('click',e=>{
 const pain=e.target.closest('[data-play="death-fail"]');if(pain&&abilitySource('Отключение болевого порога')){e.stopImmediatePropagation();applyPainFailure();save();render();return;}
 const next=e.target.closest('[data-play="next-round"]');if(next){e.stopImmediatePropagation();try{advanceAbilityRound();save();render();}catch(error){toast(error.message);}return;}
 const oldMoves=e.target.closest('[data-workflow="select-techniques"]');if(oldMoves){e.stopImmediatePropagation();openAbilityDialog({kind:'moves'});return;}
 const button=e.target.closest('[data-ability],[data-ability-use],[data-ability-move],[data-ability-select-move],[data-ability-legacy]');if(!button)return;e.stopImmediatePropagation();const d=button.dataset;
 try{
  if(d.abilityLegacy){resolveLegacyFeatGrant(d.abilityLegacy,d.credit==='yes');save();render();return;}
  if(d.abilityUse){openAbilityDialog({kind:'use',id:d.abilityUse,index:+d.actionIndex});return;}
  if(d.abilityMove){openAbilityDialog({kind:'move',id:d.abilityMove});return;}
  if(d.abilitySelectMove){const id=d.abilitySelectMove,index=state.play.pinned.indexOf(id);if(index<0)state.play.pinned.push(id);else state.play.pinned.splice(index,1);save();closeAbilityDialog();openAbilityDialog({kind:'moves'});return;}
  switch(d.ability){
   case 'close':closeAbilityDialog();render();return;
   case 'moves':case 'help':case 'psi':case 'energy':openAbilityDialog({kind:d.ability});return;
   case 'reset':openAbilityDialog({kind:'reset',period:d.period});return;
   case 'end-stance':actionSnapshot('Выйти из стойки',0);abilityState().stance=null;refreshEffectAp();break;
   case 'execute-reset':{const r=abilityState(),period=abilityDialog.period;r[period]=(r[period]||1)+1;if(period==='battle'){r.stance=null;r.flurry=false;r.tempHp=0;r.offgameUntil=0;state.play.round=1;state.play.history=[];refreshEffectAp();state.play.ap=state.play.apMax;}if(period==='day')r.incapacitated=false;closeAbilityDialog();break;}
   case 'execute-energy':{const delta=Number(document.querySelector('#ability-value').value);if(abilitySource('Варден')&&delta>0&&!document.querySelector('#ability-gm').checked)throw Error('Подтвердите разрешённый источник восстановления.');actionSnapshot('Изменить EP',0);changeEnergy(delta);closeAbilityDialog();break;}
   case 'execute-psi':castPsi(document.querySelector('#ability-skill').value,Number(document.querySelector('#ability-value').value),!!document.querySelector('#ability-critical')?.checked,!!document.querySelector('#ability-hp')?.checked);closeAbilityDialog();break;
   case 'execute-use':{const source=selectedEffectSources().find(s=>s.id===abilityDialog.id),a=ABILITY_ACTIONS[source.title][abilityDialog.index];if(a.id.startsWith('untrained')&&!document.querySelector('#ability-value').value.trim())throw Error('Укажите базовый шанс до бонуса фита.');abilityResult=useAbility(abilityDialog.id,abilityDialog.index,{value:Number(document.querySelector('#ability-value')?.value||0),skill:document.querySelector('#ability-skill')?.value,weapon:document.querySelector('#ability-weapon')?.value,weapon2:document.querySelector('#ability-weapon-second')?.value,gm:!!document.querySelector('#ability-gm')?.checked});closeAbilityDialog();break;}
   case 'execute-move':{const cost=document.querySelector('#ability-base-cost').value;const result=executeMeleeMove(abilityDialog.id,document.querySelector('#ability-skill').value,{weapon:document.querySelector('#ability-weapon').value,baseCost:cost===''?null:Number(cost),override:document.querySelector('#ability-gm').checked,combo:[document.querySelector('#ability-combo-first')?.value,document.querySelector('#ability-combo-second')?.value],comboCost:Number(document.querySelector('#ability-combo-cost')?.value)});abilityState().meleeBase={cost:cost===''?null:Number(cost),damage:document.querySelector('#ability-base-damage').value};abilityResult=result.text;closeAbilityDialog();break;}
  }save();render();
 }catch(error){const field=document.querySelector('#ability-error');if(field)field.textContent=error.message;else toast(error.message);}
},true);
migrateEffects();
render();
